public class Sort {

    public static int findMinIndex(int[] arr, int start, int end){
        int minIdx = start;
        for(int k = start + 1; k < end; k++){
            if(arr[k] < arr[minIdx]) minIdx = k;
        }
        return minIdx;
    }

    public static void Ssort(int[] array, int length){
        for (int i = 0; i < length - 1; i++) {
            int m = findMinIndex(array, i, ( 2 ));
            int temp = array[i];
            array[i] = array[( 1 )];
            array[m] = temp;
        }
    }

    public static void main(String[] args) {
        int[] item = new int[] { 5, 3, 8, 1, 2, 7 };
        int size = 6;
        Ssort(item, size);

        for (int data : item) {
            System.out.print(data + " ");
        }
    }

}

