struct Point { int x, y; };
void move(struct Point *p, int dx, int dy) {
    p->x += dx;
    p->y += dy;
}
int main(){
    struct Point p1 = {10, 20};
    struct Point p2 = {5, 8};
    move(&p1, 3, 4);
    move(&p2, p1.x, p1.y);
    printf("%d\n", p1.x + p1.y + p2.x + p2.y);
}

