def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5)+1):
        if n % i == 0:
            return False
    return True

nums = [4, 7, 10, 13, 15, 17, 20, 23]
primes = [n for n in nums if is_prime(n)]
print(sum(primes))

#include <stdio.h>

typedef struct { char* name; int code[2]; } Item;

int transform(int x) {
    return x ^ 0x0F;
}

int total(Item* p) {
    return transform(p->code[0]) + transform(p->code[1]);
}

int main() {
    Item items[2] = { { "A", {0x03, 0x0A} }, { "B", {0x05, 0x0C} } };
    int sum = 0;
    for (int i = 0; i < 2; i++) sum += total(&items[i]);
    printf("%d", sum);
    return 0;
}

